def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    sep_rows = {
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    }
    sep_cols = {
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    }

    def sections(length, separators):
        result = []
        start = 0
        for i in range(length):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_parts = sections(h, sep_rows)
    col_parts = sections(w, sep_cols)
    tiles = []
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(value != background for row in tile for value in row)
            tiles.append((r0, r1, c0, c1, tile, score))

    if not tiles or max(t[5] for t in tiles) == 0:
        return [row[:] for row in grid]

    source = max(tiles, key=lambda t: t[5])[4]
    out = [row[:] for row in grid]
    sh, sw = len(source), len(source[0])

    for r0, r1, c0, c1, _, _ in tiles:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = source[(r - r0) % sh][(c - c0) % sw]

    return out
